const { bySourceSlug } = require("../../_lib/spanish-urls.js");

module.exports = {
  eleventyComputed: {
    permalink: (data) => {
      // The bespoke Spanish homepage lives at src/index.njk.
      if (data.sourceSlug === "home") return false;
      // /opiniones/ is generated by the paginated topic archive so its
      // homepage count and article listing always use the same collection.
      if (data.sourceSlug === "reviews") return false;
      const record = bySourceSlug[data.sourceSlug];
      return record?.retired ? false : record?.to || data.permalink;
    },
    eleventyExcludeFromCollections: (data) =>
      ["home", "reviews"].includes(data.sourceSlug) || Boolean(bySourceSlug[data.sourceSlug]?.retired)
  }
};
